def rec(i: int) -> LogRecord:
    return LogRecord(f"record {i}")


class AsyncGate:
    def __init__(self) -> None:
        self.gate = asyncio.Event()
        self.entered = asyncio.Event()
        self.records: list[LogRecord] = []
        self.shutdowns = 0

    async def export(
        self, records: Sequence[LogRecord], *, gzip: bool, timeout_s: float
    ) -> ExportResult:
        self.entered.set()
        await self.gate.wait()
        self.records.extend(records)
        return ExportResult(accepted=len(records))

    async def shutdown(self) -> None:
        self.shutdowns += 1


async def test_batches_and_flush() -> None:
    exporter = AsyncInMemoryLogExporter(retries=2)
    processor = AsyncBatchProcessor(exporter, BatchOptions(max_batch_size=4, flush_interval_s=30))
    for i in range(10):
        assert processor.add(rec(i))
    await processor.flush(5)
    assert [len(b) for b in exporter.batches] == [4, 4, 2]
    assert processor.stats().sent == 10
    assert processor.stats().retries == 6
    await processor.shutdown()
    await processor.shutdown()
    assert exporter.shutdown_calls == 1
    assert not processor.add(rec(99))
    assert processor.stats().dropped == 1


