async def test_drop_oldest_and_newest() -> None:
    gate = AsyncGate()
    processor = AsyncBatchProcessor(
        gate, BatchOptions(max_queue_size=1, max_batch_size=1, flush_interval_s=30)
    )
    processor.add(rec(0))
    await asyncio.wait_for(gate.entered.wait(), 5)
    assert processor.add(rec(1))
    assert not processor.add(rec(2))
    gate.gate.set()
    await processor.shutdown(5)
    assert [r.body for r in gate.records] == ["record 0", "record 1"]

    gate2 = AsyncGate()
    oldest = AsyncBatchProcessor(
        gate2,
        BatchOptions(
            max_queue_size=1, max_batch_size=1, flush_interval_s=30, drop_policy="drop_oldest"
        ),
    )
    oldest.add(rec(0))
    await asyncio.wait_for(gate2.entered.wait(), 5)
    oldest.add(rec(1))
    assert oldest.add(rec(2))
    gate2.gate.set()
    await oldest.shutdown(5)
    assert [r.body for r in gate2.records] == ["record 0", "record 2"]


async def test_add_wait_blocks_until_space() -> None:
    gate = AsyncGate()
    processor = AsyncBatchProcessor(
        gate,
        BatchOptions(max_queue_size=1, max_batch_size=1, flush_interval_s=30, drop_policy="block"),
    )
    assert await processor.add_wait(rec(0))
    await asyncio.wait_for(gate.entered.wait(), 5)
    assert await processor.add_wait(rec(1))
    assert not processor.add(rec(2))  # add() never blocks: acts as drop_newest
    waiter = asyncio.ensure_future(processor.add_wait(rec(3)))
    await asyncio.sleep(0.05)
    assert not waiter.done()
    gate.gate.set()
    assert await asyncio.wait_for(waiter, 5)
    await processor.shutdown(5)
    assert [r.body for r in gate.records] == ["record 0", "record 1", "record 3"]


