class _SdkCancellingExporter:
    """``export`` blocks until cancelled, then raises the SDK ``CancelledError`` (what an
    exporter built on the async transport does when its task is cancelled)."""

    def __init__(self) -> None:
        self.entered = asyncio.Event()
        self.block = True
        self.exports = 0
        self.shutdowns = 0

    async def export(
        self, records: Sequence[LogRecord], *, gzip: bool, timeout_s: float
    ) -> ExportResult:
        self.exports += 1
        self.entered.set()
        if not self.block:
            return ExportResult(accepted=len(records))
        try:
            await asyncio.Event().wait()
        except asyncio.CancelledError as exc:
            raise CancelledError("logs.export: cancelled", cause=exc) from exc
        raise AssertionError("unreachable")

    async def shutdown(self) -> None:
        self.shutdowns += 1


async def test_shutdown_cancels_export_raising_sdk_cancelled_error() -> None:
    """Regression: the SDK CancelledError (also an Exception) cancels the worker; it is not
    reported as a failed export."""
    exporter = _SdkCancellingExporter()
    errors: list[Exception] = []
    processor = AsyncBatchProcessor(
        exporter,
        BatchOptions(
            flush_interval_s=0.01,
            max_export_retries=3,
            retry_backoff_s=0.01,
            on_error=lambda exc, records: errors.append(exc),
        ),
    )
    processor.add(rec(0))
    await asyncio.wait_for(exporter.entered.wait(), 5)
    stopping = asyncio.ensure_future(processor.shutdown(0.05))
    done, _ = await asyncio.wait({stopping}, timeout=5)
    if not done:
        exporter.block = False  # let the worker finish so the test can clean up
        await asyncio.wait({stopping}, timeout=5)
        pytest.fail("AsyncBatchProcessor.shutdown() hung: the cancellation was swallowed")
    assert errors == []
    assert exporter.exports == 1
    assert exporter.shutdowns == 1
    assert processor.stats().retries == 0
